/* Anthropic Theme Variables */
.anthropic-theme {
  background-color: #FAF9F7;
  min-height: 100vh;
}

/* Custom Container */
.custom-container {
  max-width: 1200px;
  margin: 0 auto;
  padding: 0 24px;
}

/* Hero Section */
.club-hero-section {
  padding: 80px 0 60px 0;
  background-color: #FAF9F7;
  border-bottom: 1px solid #E5E5E5;
}

.hero-content {
  text-align: center;
  max-width: 700px;
  margin: 0 auto;
}

.hero-title {
  font-size: 3.5rem;
  font-weight: 500;
  color: #1A1A1A;
  margin-bottom: 1rem;
  line-height: 1.2;
}

.hero-subtitle {
  font-size: 1.25rem;
  color: #E17B47;
  font-weight: 500;
  margin-bottom: 1rem;
}

.hero-description {
  font-size: 1.125rem;
  color: #666666;
  line-height: 1.6;
  margin: 0;
}

/* Section Styles */
.clubs-section,
.events-section {
  padding: 80px 0;
  background-color: #FAF9F7;
}

.membership-benefits-section {
  padding: 80px 0;
  background-color: #F0EDE8;
}

.join-cta-section {
  padding: 80px 0;
  background-color: #1A1A1A;
}

.section-header {
  text-align: center;
  margin-bottom: 4rem;
  max-width: 600px;
  margin-left: auto;
  margin-right: auto;
}

.section-title {
  font-size: 2.5rem;
  font-weight: 500;
  color: #1A1A1A;
  margin-bottom: 1rem;
  line-height: 1.3;
}

.section-description {
  font-size: 1.125rem;
  color: #666666;
  line-height: 1.6;
  margin: 0;
}

/* Clubs Grid */
.clubs-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(320px, 1fr));
  gap: 2rem;
}

.club-card {
  background: #FFFFFF;
  border-radius: 16px;
  overflow: hidden;
  box-shadow: 0 2px 8px rgba(0, 0, 0, 0.04);
  border: 1px solid #E5E5E5;
  transition: all 0.3s ease;
}

.club-card:hover {
  transform: translateY(-4px);
  box-shadow: 0 8px 32px rgba(0, 0, 0, 0.12);
  border-color: #E17B47;
}

.club-image {
  width: 100%;
  height: 200px;
  overflow: hidden;
}

.club-image img {
  width: 100%;
  height: 100%;
  object-fit: cover;
}

.club-content {
  padding: 2rem;
}

.club-header {
  display: flex;
  align-items: center;
  gap: 1rem;
  margin-bottom: 1rem;
}

.club-icon {
  width: 50px;
  height: 50px;
  border-radius: 50%;
  background: #F0EDE8;
  display: flex;
  align-items: center;
  justify-content: center;
  flex-shrink: 0;
}


.club-title {
  font-size: 1.25rem;
  font-weight: 500;
  color: #1A1A1A;
  margin: 0;
  flex: 1;
}

.club-category {
  background: #E17B47;
  color: white;
  padding: 0.25rem 0.75rem;
  border-radius: 20px;
  font-size: 0.75rem;
  font-weight: 500;
}

.club-description {
  color: #666666;
  line-height: 1.6;
  margin-bottom: 1.5rem;
  font-size: 0.95rem;
}

.club-benefits {
  margin-bottom: 1.5rem;
}

.benefits-title {
  color: #1A1A1A;
  font-size: 0.875rem;
  font-weight: 600;
  display: block;
  margin-bottom: 0.75rem;
}

.benefits-list {
  list-style: none;
  padding: 0;
  margin: 0;
}

.benefits-list li {
  position: relative;
  padding-left: 1.5rem;
  margin-bottom: 0.5rem;
  color: #333333;
  line-height: 1.5;
  font-size: 0.875rem;
}

.benefits-list li::before {
  content: '✓';
  position: absolute;
  left: 0;
  color: #E17B47;
  font-weight: 600;
}

.club-stats {
  margin-bottom: 1.5rem;
}

.member-count {
  color: #666666;
  font-size: 0.875rem;
  display: flex;
  align-items: center;
  gap: 0.5rem;
}

.club-button {
  width: 100%;
  background: #E17B47;
  color: white;
  border: none;
  padding: 0.875rem 1.5rem;
  border-radius: 8px;
  font-weight: 500;
  cursor: pointer;
  transition: all 0.3s ease;
  font-size: 0.875rem;
}

.club-button:hover {
  background: #1A1A1A;
  transform: translateY(-1px);
}

/* Features Grid */
.features-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(250px, 1fr));
  gap: 2rem;
}

.feature-card {
  background: #FFFFFF;
  border-radius: 16px;
  padding: 2rem;
  text-align: center;
  box-shadow: 0 2px 8px rgba(0, 0, 0, 0.04);
  border: 1px solid #E5E5E5;
  transition: all 0.3s ease;
}

.feature-card:hover {
  transform: translateY(-4px);
  box-shadow: 0 8px 32px rgba(0, 0, 0, 0.12);
  border-color: #E17B47;
}

.feature-icon {
  width: 80px;
  height: 80px;
  border-radius: 50%;
  background: #E17B47;
  display: flex;
  align-items: center;
  justify-content: center;
  margin: 0 auto 1.5rem auto;
}


.feature-title {
  font-size: 1.25rem;
  font-weight: 500;
  color: #1A1A1A;
  margin-bottom: 0.75rem;
}

.feature-description {
  color: #666666;
  line-height: 1.6;
  margin: 0;
  font-size: 1rem;
}

/* Events Grid */
.events-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(300px, 1fr));
  gap: 2rem;
}

/* Events Upcoming - Blur Effect */
.events-upcoming {
  filter: blur(3px);
  opacity: 0.6;
  pointer-events: none;
  position: relative;
}

.events-upcoming::after {
  content: '準備中';
  position: absolute;
  top: 50%;
  left: 50%;
  transform: translate(-50%, -50%);
  background: rgba(26, 26, 26, 0.9);
  color: white;
  padding: 1rem 2rem;
  border-radius: 8px;
  font-size: 1.5rem;
  font-weight: 500;
  pointer-events: none;
  z-index: 10;
  backdrop-filter: blur(10px);
  border: 2px solid rgba(255, 255, 255, 0.1);
}

.event-card {
  background: #FFFFFF;
  border-radius: 16px;
  display: flex;
  overflow: hidden;
  box-shadow: 0 2px 8px rgba(0, 0, 0, 0.04);
  border: 1px solid #E5E5E5;
  transition: all 0.3s ease;
}

.event-card:hover {
  transform: translateY(-4px);
  box-shadow: 0 8px 32px rgba(0, 0, 0, 0.12);
}

.event-date {
  background: #F0EDE8;
  padding: 1.5rem;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  min-width: 100px;
  text-align: center;
}

.event-month {
  color: #E17B47;
  font-size: 0.75rem;
  font-weight: 600;
  text-transform: uppercase;
  margin-bottom: 0.25rem;
}

.event-day {
  color: #1A1A1A;
  font-size: 1.5rem;
  font-weight: 600;
}

.event-content {
  padding: 1.5rem;
  flex: 1;
}

.event-title {
  font-size: 1.125rem;
  font-weight: 500;
  color: #1A1A1A;
  margin-bottom: 0.75rem;
}

.event-meta {
  margin-bottom: 0.75rem;
}

.event-location,
.event-time {
  color: #666666;
  font-size: 0.875rem;
  margin-bottom: 0.25rem;
  display: flex;
  align-items: center;
  gap: 0.5rem;
}

.event-club-tag {
  background: #E17B47;
  color: white;
  padding: 0.25rem 0.75rem;
  border-radius: 20px;
  font-size: 0.75rem;
  font-weight: 500;
  display: inline-block;
  margin-bottom: 0.75rem;
}

.event-description {
  color: #666666;
  line-height: 1.6;
  margin: 0;
  font-size: 0.875rem;
}

/* Join CTA Section */
.cta-content {
  text-align: center;
  max-width: 600px;
  margin: 0 auto;
}

.cta-title {
  font-size: 2.5rem;
  font-weight: 500;
  color: #FFFFFF;
  margin-bottom: 1rem;
  line-height: 1.3;
}

.cta-description {
  font-size: 1.125rem;
  color: rgba(255, 255, 255, 0.9);
  line-height: 1.6;
  margin-bottom: 2rem;
}

.cta-buttons {
  display: flex;
  gap: 1rem;
  justify-content: center;
  flex-wrap: wrap;
}

.cta-button {
  padding: 1rem 2rem;
  border-radius: 8px;
  font-weight: 500;
  cursor: pointer;
  transition: all 0.3s ease;
  font-size: 1rem;
  border: 2px solid transparent;
}

.cta-button.primary {
  background: #E17B47;
  color: white;
  border-color: #E17B47;
}

.cta-button.primary:hover {
  background: transparent;
  color: #E17B47;
  border-color: #E17B47;
}

.cta-button.secondary {
  background: transparent;
  color: white;
  border-color: white;
}

.cta-button.secondary:hover {
  background: white;
  color: #1A1A1A;
}

/* Responsive Design */
@media (max-width: 768px) {
  .custom-container {
    padding: 0 16px;
  }

  .club-hero-section,
  .clubs-section,
  .membership-benefits-section,
  .events-section,
  .join-cta-section {
    padding: 60px 0;
  }

  .hero-title {
    font-size: 2.5rem;
  }

  .section-title,
  .cta-title {
    font-size: 2rem;
  }

  .clubs-grid {
    grid-template-columns: 1fr;
  }

  .features-grid {
    grid-template-columns: 1fr;
  }

  .events-grid {
    grid-template-columns: 1fr;
  }

  .event-card {
    flex-direction: column;
  }

  .event-date {
    flex-direction: row;
    padding: 1rem;
    min-width: auto;
    justify-content: flex-start;
    gap: 0.5rem;
  }

  .cta-buttons {
    flex-direction: column;
    align-items: center;
  }

  .cta-button {
    width: 100%;
    max-width: 300px;
  }
}

@media (max-width: 480px) {
  .hero-title {
    font-size: 2rem;
  }

  .section-title,
  .cta-title {
    font-size: 1.75rem;
  }

  .club-content {
    padding: 1.5rem;
  }

  .feature-card {
    padding: 1.5rem;
  }

  .event-content {
    padding: 1.25rem;
  }
}

